#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;

int add_mod(int a, int b) {
    int res = a + b;
    if (res >= MOD) res -= MOD;
    return res;
}

int sub_mod(int a, int b) {
    int res = a - b;
    if (res < 0) res += MOD;
    return res;
}

int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

ll n;
int k;
vector<vector<int>> multiply_matrices(const vector<vector<int>>& A, const vector<vector<int>>& B) {
    vector<vector<int>> C(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            for (int t = 0; t <= k; t++) {
                C[i][t] = add_mod(C[i][t], mul_mod(A[i][j], B[j][t]));
            }
        }
    }
    return C;
}

vector<vector<int>> prefix[100];

vector<vector<int>> shift(const vector<vector<int>>& mat) {
    vector<vector<int>> res(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            int ni = i;
            if (ni < k) ni = (ni + k - 1) % k;
            int nj = j;
            if (nj < k) nj = (nj + k - 1) % k;
            res[i][j] = mat[ni][nj];
        }
    }
    return res;
}

void setup() {
    ll temp = n;
    int count_digits = 0;
    while (temp > 0) {
        temp /= k;
        count_digits++;
    }
    prefix[0].resize(k + 1, vector<int>(k + 1, 0));
    for (int i = 1; i < k; i++) {
        prefix[0][i][i] = 1;
    }
    prefix[0][0][k] = 1;
    prefix[0][k][0] = MOD - 1;
    prefix[0][k][k] = 2;

    for (int step = 0; step < count_digits; step++) {
        prefix[step + 1] = prefix[step];
        auto current = prefix[step];
        for (int i = 1; i <= k - 1; i++) {
            current = shift(current);
            prefix[step + 1] = multiply_matrices(prefix[step + 1], current);
        }
    }
}

vector<vector<int>> get_matrix(ll n_value) {
    if (n_value == 0) {
        vector<vector<int>> c(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; i++) c[i][i] = 1;
        return c;
    }
    ll pw = 1;
    int d = 0;
    while (pw <= n_value / k) {
        pw *= k;
        d++;
    }
    if (n_value == pw) return prefix[d];
    ll steps = n_value / pw;
    ll rem = n_value - steps * pw;
    auto matrix_curr = get_matrix(0);
    auto coef = prefix[d];
    for (int i = 0; i < steps; i++) {
        matrix_curr = multiply_matrices(matrix_curr, coef);
        coef = shift(coef);
    }
    auto matrix_left = get_matrix(rem);
    for (int i = 0; i < steps; i++) {
        matrix_left = shift(matrix_left);
    }
    return multiply_matrices(matrix_curr, matrix_left);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    setup();
    auto answer = get_matrix(n);
    cout << answer[k][k];
    return 0;
}
